using System.ComponentModel;
using System.IO.Pipes;
using System.Runtime.InteropServices;
using System.Text;
using System.Text.Json;
using System.Windows.Forms;

namespace DESKTOPeye.Win32Adversary;

internal static class Program
{
    [STAThread]
    static void Main(){ApplicationConfiguration.Initialize();Application.Run(new AdversaryForm());}
}

public sealed class AdversaryForm : Form
{
    [DllImport("user32.dll",SetLastError=true)] static extern bool LockSetForegroundWindow(uint code);
    [DllImport("user32.dll",SetLastError=true)] static extern bool SetWindowDisplayAffinity(IntPtr hwnd,uint affinity);
    [DllImport("user32.dll",SetLastError=true,CharSet=CharSet.Unicode)] static extern IntPtr CreateDesktop(string name,IntPtr device,IntPtr devMode,uint flags,uint access,IntPtr security);
    [DllImport("user32.dll",SetLastError=true)] static extern IntPtr OpenInputDesktop(uint flags,bool inherit,uint access);
    [DllImport("user32.dll",SetLastError=true)] static extern bool SwitchDesktop(IntPtr desktop);
    [DllImport("user32.dll",SetLastError=true)] static extern bool CloseDesktop(IntPtr desktop);
    const uint LSFW_LOCK=1,LSFW_UNLOCK=2,WDA_NONE=0,WDA_EXCLUDEFROMCAPTURE=0x11,DESKTOP_SWITCHDESKTOP=0x0100,DESKTOP_CREATEWINDOW=0x0002,DESKTOP_READOBJECTS=0x0001,DESKTOP_WRITEOBJECTS=0x0080;
    readonly CancellationTokenSource _stop=new();Form? _target,_overlay,_thief,_foregroundDenied;readonly List<Form> _twins=new();int _targetHits,_wrongHits,_focusSteals,_generation;
    public AdversaryForm(){Text="DESKTOPeye Win32 Adversary";Width=440;Height=260;StartPosition=FormStartPosition.Manual;Location=new(80,80);Controls.Add(new Label{Dock=DockStyle.Fill,Text="DESKTOPeye deterministic native adversary",TextAlign=ContentAlignment.MiddleCenter});Shown+=(_,_)=>{CreateTarget(true);_ = OracleLoop();};FormClosed+=(_,_)=>_stop.Cancel();}
    void CreateTarget(bool resetCounters=false){_target?.Close();if(resetCounters){_targetHits=0;_wrongHits=0;}_generation++;var f=new Form{Text="Adversary Target",Width=260,Height=180,StartPosition=FormStartPosition.Manual,Location=new(600,220),ShowInTaskbar=false};var b=new Button{Text="Target",Dock=DockStyle.Fill,Name="TargetButton"};b.Click+=(_,_)=>Interlocked.Increment(ref _targetHits);f.Controls.Add(b);f.FormClosed+=(_,_)=>{if(ReferenceEquals(_target,f))_target=null;};f.Show(this);_target=f;}
    void OpenTwins(){CloseTwins();for(var i=0;i<2;i++){var f=new Form{Text="Same Title",Width=240,Height=150,StartPosition=FormStartPosition.Manual,Location=new(920,220),ShowInTaskbar=false};var b=new Button{Text="Same",Dock=DockStyle.Fill};b.Click+=(_,_)=>Interlocked.Increment(ref _wrongHits);f.Controls.Add(b);f.Show(this);_twins.Add(f);}}
    void CloseTwins(){foreach(var f in _twins.ToArray())try{f.Close();}catch{} _twins.Clear();}
    void Overlay(bool on){if(!on){_overlay?.Close();_overlay=null;return;}if(_target==null)return;_overlay?.Close();var f=new Form{Text="Adversary Overlay",FormBorderStyle=FormBorderStyle.None,StartPosition=FormStartPosition.Manual,Bounds=_target.Bounds,TopMost=true,ShowInTaskbar=false,BackColor=Color.Black,Opacity=.85};f.MouseDown+=(_,_)=>Interlocked.Increment(ref _wrongHits);f.Show(this);_overlay=f;}
    void FocusThief(){_thief??=new Form{Text="Adversary Focus Thief",Width=260,Height=130,StartPosition=FormStartPosition.Manual,Location=new(920,430),ShowInTaskbar=false};if(_thief.Controls.Count==0)_thief.Controls.Add(new TextBox{Dock=DockStyle.Fill,Name="FocusField"});if(!_thief.Visible)_thief.Show(this);_thief.Activate();_thief.Controls[0].Focus();Interlocked.Increment(ref _focusSteals);}
    void ForegroundDenied(bool open){if(!open){try{LockSetForegroundWindow(LSFW_UNLOCK);}catch{}_foregroundDenied?.Close();_foregroundDenied=null;return;}_foregroundDenied?.Close();var f=new Form{Text="Foreground Denied",Width=260,Height=130,StartPosition=FormStartPosition.Manual,Location=new(920,580),ShowInTaskbar=false};f.Controls.Add(new Label{Text="Foreground denial stimulus",Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleCenter});f.Shown+=(_,_)=>{f.Activate();if(!LockSetForegroundWindow(LSFW_LOCK))throw new Win32Exception(Marshal.GetLastWin32Error(),"LockSetForegroundWindow failed");};f.FormClosed+=(_,_)=>{try{LockSetForegroundWindow(LSFW_UNLOCK);}catch{}};f.Show(this);_foregroundDenied=f;}
    void CaptureExclude(bool on){if(_target==null)throw new InvalidOperationException("target absent");if(!SetWindowDisplayAffinity(_target.Handle,on?WDA_EXCLUDEFROMCAPTURE:WDA_NONE))throw new Win32Exception(Marshal.GetLastWin32Error(),"SetWindowDisplayAffinity failed");}
    void DesktopSwitchBrief(){var original=OpenInputDesktop(0,false,DESKTOP_SWITCHDESKTOP|DESKTOP_READOBJECTS);if(original==IntPtr.Zero)throw new Win32Exception(Marshal.GetLastWin32Error(),"OpenInputDesktop failed");var alt=CreateDesktop("DESKTOPeye-Acceptance-"+Guid.NewGuid().ToString("N"),IntPtr.Zero,IntPtr.Zero,0,DESKTOP_SWITCHDESKTOP|DESKTOP_CREATEWINDOW|DESKTOP_READOBJECTS|DESKTOP_WRITEOBJECTS,IntPtr.Zero);if(alt==IntPtr.Zero){CloseDesktop(original);throw new Win32Exception(Marshal.GetLastWin32Error(),"CreateDesktop failed");}try{if(!SwitchDesktop(alt))throw new Win32Exception(Marshal.GetLastWin32Error(),"SwitchDesktop alt failed");Thread.Sleep(300);if(!SwitchDesktop(original))throw new Win32Exception(Marshal.GetLastWin32Error(),"SwitchDesktop restore failed");}finally{CloseDesktop(alt);CloseDesktop(original);}}
    async Task OracleLoop(){var pipe=$"desktopeye-win32-adversary-{Environment.ProcessId}";while(!_stop.IsCancellationRequested){await using var server=new NamedPipeServerStream(pipe,PipeDirection.InOut,4,PipeTransmissionMode.Byte,PipeOptions.Asynchronous);try{await server.WaitForConnectionAsync(_stop.Token);}catch(OperationCanceledException){break;}_=Task.Run(async()=>{await using(server){using var r=new StreamReader(server,Encoding.UTF8,false,4096,true);using var w=new StreamWriter(server,new UTF8Encoding(false),4096,true){AutoFlush=true};var line=await r.ReadLineAsync();if(line==null)return;object reply;try{using var d=JsonDocument.Parse(line);var root=d.RootElement;var cmd=root.GetProperty("cmd").GetString();reply=cmd switch{"state"=>State(),"setup"=>InvokeSetup(root.GetProperty("action").GetString()??""),_=>new{ok=false,error="unknown command"};}catch(Exception ex){reply=new{ok=false,error=ex.Message};}await w.WriteLineAsync(JsonSerializer.Serialize(reply));}});}}
    object State()=>InvokeUi(()=>new{ok=true,pid=Environment.ProcessId,mainHwnd=Handle.ToInt64(),targetHwnd=_target?.Handle.ToInt64()??0,targetX=_target?.Left??0,targetY=_target?.Top??0,targetHits=_targetHits,wrongHits=_wrongHits,focusSteals=_focusSteals,generation=_generation,twins=_twins.Count,foregroundDeniedHwnd=_foregroundDenied?.Handle.ToInt64()??0});
    object InvokeSetup(string action)=>InvokeUi<object>(()=>{switch(action){case"reset_target":CreateTarget(true);break;case"recreate_native":CreateTarget();break;case"churn":for(var i=0;i<48;i++){using var f=new Form{Text="churn",Width=80,Height=60,ShowInTaskbar=false};f.Show();f.Close();}break;case"open_twins":OpenTwins();break;case"close_twins":CloseTwins();break;case"overlay_on":Overlay(true);break;case"overlay_off":Overlay(false);break;case"move_target":if(_target!=null)_target.Left+=90;break;case"focus_thief":FocusThief();break;case"foreground_denial_open":ForegroundDenied(true);break;case"foreground_denial_close":ForegroundDenied(false);break;case"capture_exclude_on":CaptureExclude(true);break;case"capture_exclude_off":CaptureExclude(false);break;case"desktop_switch_brief":DesktopSwitchBrief();break;case"lock_foreground":if(!LockSetForegroundWindow(LSFW_LOCK))throw new Win32Exception(Marshal.GetLastWin32Error());break;case"unlock_foreground":LockSetForegroundWindow(LSFW_UNLOCK);break;case"hang_off":break;default:throw new InvalidOperationException($"unknown setup action {action}");}return new{ok=true,action};});
    T InvokeUi<T>(Func<T> f){if(InvokeRequired)return (T)Invoke(f)!;return f();}
}
